package org.eclipse.jdt.ui;

import org.eclipse.core.resources.IResourceStatus;
import org.eclipse.core.runtime.CoreException;
import org.eclipse.core.runtime.IStatus;

public class ProblemsLabelDecorator {
    public int getPackageErrorTicksFromMarkers(CoreException e) {
        // Assuming e.getStatus().getCode() has no side effects
        if (e.getStatus().getCode() == org.eclipse.core.resources.IResourceStatus.MARKER_NOT_FOUND || e.getStatus().getCode() == org.eclipse.core.resources.IResourceStatus.RESOURCE_NOT_FOUND) {
            return 0;
        }
        return 1;
    }
}

negativeExample:
package org.eclipse.jdt.ui;

import org.eclipse.core.resources.IResourceStatus;
import org.eclipse.core.runtime.CoreException;
import org.eclipse.core.runtime.IStatus;

public class ProblemsLabelDecorator {
    public int getPackageErrorTicksFromMarkers(CoreException e) {
        // This condition should not match as it's different
        if (e.getStatus().getCode() == IResourceStatus.OTHER_ERROR) {
            return 0;
        }
        // This condition should not match as it already includes RESOURCE_NOT_FOUND
        if (e.getStatus().getCode() == IResourceStatus.MARKER_NOT_FOUND || e.getStatus().getCode() == IResourceStatus.RESOURCE_NOT_FOUND) {
            return 0;
        }
        return 1;
    }
}
